def _load_playwright_browser_module():
    """从源码文件加载 playwright_browser，确保开发态/打包态使用同一逻辑。"""
    global _PLAYWRIGHT_BROWSER_MODULE_CACHE
    if _PLAYWRIGHT_BROWSER_MODULE_CACHE is not None:
        return _PLAYWRIGHT_BROWSER_MODULE_CACHE

    candidates = []
    if getattr(sys, 'frozen', False):
        candidates.extend([
            os.path.join(RUNTIME_APP_DIR, "_internal", "playwright_browser.py"),
            os.path.join(RUNTIME_APP_DIR, "playwright_browser.py"),
        ])
    else:
        candidates.append(os.path.join(os.path.dirname(os.path.abspath(__file__)), "playwright_browser.py"))

    for module_path in candidates:
        if not os.path.isfile(module_path):
            continue
        spec = importlib.util.spec_from_file_location("playwright_browser_runtime", module_path)
        if spec is None or spec.loader is None:
            continue
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)
        _PLAYWRIGHT_BROWSER_MODULE_CACHE = module
        return module

    import playwright_browser as module  # fallback
    _PLAYWRIGHT_BROWSER_MODULE_CACHE = module
    return module


def _set_windows_app_user_model_id():
    """为 Windows 任务栏设置稳定的应用标识，避免显示为默认通用图标。"""
    if sys.platform != 'win32':
        return
    try:
        ctypes.windll.shell32.SetCurrentProcessExplicitAppUserModelID(WINDOWS_APP_USER_MODEL_ID)
    except Exception:
        pass

# === 【关键修复】PyInstaller frozen GUI 环境句柄修复 ===
# 必须在任何其他代码之前执行，确保 stdin/stdout/stderr 有效
if __name__ == '__main__':
    is_frozen = getattr(sys, 'frozen', False)
    if is_frozen and sys.platform == 'win32':
        import io
        def fix_std_handle(handle_name, fd, mode):
            try:
                handle = getattr(sys, handle_name)
                # 如果句柄是 None 或无效，尝试恢复或替换
                if handle is None:
                    try:
                        # 尝试从 FD 恢复（适用于子进程 Pipe 继承）
                        setattr(sys, handle_name, os.fdopen(fd, mode, buffering=1, encoding='utf-8'))
                    except:
                        # 失败则说明没有关联的 Pipe 或 Console，回退到 devnull
                        setattr(sys, handle_name, open(os.devnull, mode))
                else:
                    try:
                        handle.fileno()
                    except (OSError, io.UnsupportedOperation, AttributeError):
                        try:
                            handle.close()
                        except: pass
                        try:
                            setattr(sys, handle_name, os.fdopen(fd, mode, buffering=1, encoding='utf-8'))
                        except:
                            setattr(sys, handle_name, open(os.devnull, mode))
            except Exception:
                try:
                    setattr(sys, handle_name, io.StringIO('') if 'r' in mode else io.StringIO())
                except: pass

        fix_std_handle('stderr', 2, 'w')
        fix_std_handle('stdout', 1, 'w')
        # 关键：打包子进程命令通道依赖 stdin（用于 COOKIES/PING 等指令）
        # 部分机器在 windowed frozen 下 stdin 句柄可能无效，需显式修复
        fix_std_handle('stdin', 0, 'r')

    # === 【关键】环境修复 ===
    # 确保在启动任何功能前，PLAYWRIGHT_BROWSERS_PATH 等环境变量已正确设置
    playwright_fix.setup_playwright_environment()
    playwright_fix.fix_windows_path_env()

# === 【关键】强制 yt-dlp 输出 UTF-8 ===
# 中文 Windows 下 yt-dlp 会检测控制台编码并使用 GBK(cp936) 输出标题等文本，
# 而 subprocess 调用使用 encoding='utf-8' 解码，导致 Bilibili 等中文平台标题乱码。
# 设置 PYTHONIOENCODING=utf-8 强制 yt-dlp (Python 程序) 输出 UTF-8，从根本上解决编码不一致。
# 同时配合 decode_subprocess_bytes() 用于二进制捕获的降级处理。
os.environ.setdefault('PYTHONIOENCODING', 'utf-8')

# === 【关键修复】stdout/stderr 编码修复 ===
# 中文 Windows 默认 stdout 编码为 GBK，无法输出 \ufffd 等特殊 Unicode 字符，
# 导致 print() 抛出 UnicodeEncodeError 从而中断业务流程（如历史记录保存）。
# 强制将 stdout/stderr 设为 UTF-8 + errors='replace'，确保任何字符都不会崩溃。
try:
    import io as _io
    for _stream_name in ('stdout', 'stderr'):
        _stream = getattr(sys, _stream_name, None)
        if _stream is None:
            setattr(sys, _stream_name, open(os.devnull, 'w', encoding='utf-8', errors='replace'))
        elif hasattr(_stream, 'reconfigure'):
            try:
                _stream.reconfigure(encoding='utf-8', errors='replace')
            except Exception:
                pass
        elif hasattr(_stream, 'encoding') and (_stream.encoding or '').lower() not in ('utf-8', 'utf8'):
            try:
                setattr(sys, _stream_name, _io.TextIOWrapper(
                    _stream.buffer, encoding='utf-8', errors='replace', line_buffering=True
                ))
            except Exception:
                pass
except Exception:
    pass

# Ensure relative executable calls (yt-dlp.exe/ffmpeg.exe/deno.exe) work
# when users launch from shortcuts on a new machine.
if getattr(sys, 'frozen', False):
    try:
        os.chdir(RUNTIME_APP_DIR)
    except Exception:
        pass

# === 【关键】PyInstaller 打包修复 - 防止多进程重复启动主窗口 ===
if __name__ == '__main__':
    # 如果是 playwright 启动子进程，直接运行 launcher 逻辑并退出
    if len(sys.argv) > 1 and sys.argv[1] == "--playwright-launcher":
        try:
            launcher_script = sys.argv[2] if len(sys.argv) > 2 else ""
            if launcher_script and os.path.isfile(launcher_script):
                import runpy

                # 统一开发态与打包态：都执行同一份 _launcher.py
                script_argv = [launcher_script] + sys.argv[3:]
                old_argv = sys.argv
                try:
                    sys.argv = script_argv
                    runpy.run_path(launcher_script, run_name="__main__")
                finally:
                    sys.argv = old_argv
            else:
                # 兼容回退：若脚本不存在，继续使用内置 launcher
                _load_playwright_browser_module().run_launcher()
        except Exception as e:
            try:
                print(t_format("[BROWSER] ERROR: BROWSER_UNKNOWN|启动子进程失败: {}", e), flush=True)
            except:
                pass
        sys.exit(0)
        
    multiprocessing.freeze_support()

# === 【关键】Deno 运行时配置 - yt-dlp 需要 Deno 来解决 YouTube JS 挑战 ===
# 参考: https://github.com/yt-dlp/yt-dlp/wiki/Installation#javascript-runtime
if sys.platform == 'win32':
    # 1. 检查应用程序目录（打包后）
    app_dir = RUNTIME_APP_DIR
    bundled_deno = os.path.join(app_dir, 'deno.exe')
    if os.path.exists(bundled_deno):
        if app_dir not in os.environ.get('PATH', ''):
            os.environ['PATH'] = app_dir + os.pathsep + os.environ.get('PATH', '')
    else:
        # 2. 检查用户目录下的 .deno\bin
        deno_path = os.path.join(os.environ.get('USERPROFILE', ''), '.deno', 'bin')
        if os.path.exists(deno_path) and deno_path not in os.environ.get('PATH', ''):
            os.environ['PATH'] = deno_path + os.pathsep + os.environ.get('PATH', '')


