        # 创建滚动内容容器
        basic_content = QWidget()
        basic_layout = QVBoxLayout(basic_content)
        
        # 设置选项卡的主布局
        basic_tab_layout = QVBoxLayout(basic_tab)
        basic_tab_layout.addWidget(basic_scroll)
        basic_scroll.setWidget(basic_content)
        
        # 设置内容布局的间距，增加组件之间的空间
        basic_layout.setSpacing(12)
